import React,{useEffect,useRef,useState} from 'react';import{createRoot}from'react-dom/client';import*as XLSX from 'xlsx';import{Play,Square,RotateCcw,Download,Upload,Plus,Minus,Users,Timer,BarChart3,Settings,Volume2,Undo2}from'lucide-react';import './style.css';
const demo=[['Emma','MARTIN'],['Lucas','DUPONT'],['Chloé','BERNARD'],['Hugo','MOREL'],['Léa','PETIT'],['Nathan','ROBERT'],['Inès','DURAND'],['Louis','THOMAS']].map(([first,last],i)=>({id:crypto.randomUUID(),first,last,group:i<4?'A':'B',target12:10,target6:11,sex:'',vma:0}));
const initialRaces=[{id:'r1',group:'A',duration:12},{id:'r2',group:'B',duration:12},{id:'r3',group:'A',duration:6},{id:'r4',group:'B',duration:6}];const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};const fmt=t=>{const s=Math.max(0,Math.floor(t/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}.${Math.floor((t%1000)/100)}`};const speed=(distance,ms)=>ms>0?distance/(ms/3600000)/1000:0;const rnd=n=>Number(n||0).toFixed(2);const dl=(name,content,type='application/json')=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};

function VelocityChart({series,mode='laps'}){
 const W=760,H=270,L=52,R=18,T=18,B=42;
 const values=series.flatMap(x=>[...x.points.map(p=>p.v),x.target]).filter(v=>Number.isFinite(v)&&v>0);
 if(!values.length)return <p className="muted">Aucun passage complet enregistré pour ce graphique.</p>;
 const lo=Math.max(0,Math.floor((Math.min(...values)-1)/1)*1),hi=Math.ceil(Math.max(...values)+1);
 const maxX=mode==='progress'?100:Math.max(1,...series.flatMap(x=>x.points.map(p=>p.x)));
 const X=x=>L+x/maxX*(W-L-R),Y=y=>T+(hi-y)/(hi-lo||1)*(H-T-B);
 const palette=['#007cba','#e87928','#8057bc','#15966c'];
 return <div className="velocity-chart"><svg viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Graphique des vitesses réelles et cibles" preserveAspectRatio="xMidYMid meet">
 {[0,1,2,3,4].map(i=>{const v=lo+(hi-lo)*i/4;return <g key={i}><line x1={L} x2={W-R} y1={Y(v)} y2={Y(v)} stroke="#e1e8ef"/><text x={L-9} y={Y(v)+4} textAnchor="end" fontSize="12" fill="#60758a">{v.toFixed(1)}</text></g>})}
 {Array.from({length:mode==='progress'?5:Math.min(maxX,12)+1},(_,i)=>{const x=mode==='progress'?i*25:i;return <g key={i}><line x1={X(x)} x2={X(x)} y1={H-B} y2={H-B+5} stroke="#718096"/><text x={X(x)} y={H-B+20} textAnchor="middle" fontSize="12" fill="#60758a">{mode==='progress'?x+'%':x}</text></g>})}
 <text x="15" y="13" fontSize="12" fill="#60758a">km/h</text>
 {series.map((item,i)=>{const color=palette[i%palette.length],pts=item.points;return <g key={item.label}>
 <line x1={X(0)} x2={X(maxX)} y1={Y(item.target)} y2={Y(item.target)} stroke={color} strokeWidth="1.8" strokeDasharray="7 5" opacity=".75"/>
 {pts.length>0&&<polyline fill="none" stroke={color} strokeWidth="3" strokeLinejoin="round" strokeLinecap="round" points={pts.map(p=>`${X(p.x)},${Y(p.v)}`).join(' ')}/>}
 {pts.map((p,j)=><circle key={j} cx={X(p.x)} cy={Y(p.v)} r="4" fill={color}><title>{item.label} · tour {p.tour} · {rnd(p.v)} km/h</title></circle>)}
 </g>})}</svg><div className="chart-legend">{series.map((item,i)=><span key={item.label}><i style={{background:palette[i%palette.length]}}/>{item.label} — réel (trait plein), cible (pointillé : {rnd(item.target)} km/h)</span>)}</div><p className="muted">{mode==='progress'?'Axe horizontal : progression dans la durée de chaque course (0 à 100 %). Les vitesses restent calculées par tour complet de 200 m.':'Axe horizontal : numéro du tour complet de 200 m.'}</p></div>
}
function PedagogicalAnalysis({report}){
 const {points,target,variation,projectDeviation,avg,limit,r,distance}=report;
 if(points.length<2)return <div className="pedagogy"><h3>Analyse pédagogique automatique</h3><p>Au moins deux tours complets sont nécessaires pour analyser l'évolution de l'allure. Les résultats restent consultables ci-dessus.</p></div>;
 const n=points.length, first=points.slice(0,Math.max(1,Math.ceil(n/3))),last=points.slice(-Math.max(1,Math.ceil(n/3)));
 const mean=a=>a.reduce((sum,p)=>sum+p.v,0)/a.length;
 const firstV=mean(first),lastV=mean(last),trend=(lastV/firstV-1)*100;
 const initialGap=target?(firstV/target-1)*100:null;
 const messages=[];
 if(variation!==null){if(variation<=2)messages.push('Régularité excellente : 3/3 selon le barème.');else if(variation<=4)messages.push('Régularité très satisfaisante : 2,5/3 sur cette course.');else if(variation<=6)messages.push('Régularité satisfaisante : 2/3 sur cette course.');else if(variation<=10)messages.push('Régularité perfectible : réduire les variations de vitesse entre les tours.');else messages.push('Allure irrégulière : travailler la stabilité des vitesses par tour.');}
 if(initialGap!==null){if(initialGap>5)messages.push('Départ rapide par rapport au projet : essayer de mieux doser les premiers tours.');else if(initialGap< -5)messages.push('Départ prudent par rapport au projet : rechercher plus tôt l’allure prévue.');else messages.push('Départ proche de la vitesse cible.');}
 if(trend< -5)messages.push('Ralentissement en fin de course : travailler la gestion de l’effort pour conserver l’allure.');else if(trend>5)messages.push('Accélération en fin de course : une allure initiale plus proche du projet pourrait améliorer la répartition de l’effort.');else messages.push('Vitesse globalement maintenue entre le début et la fin.');
 if(target&&distance>0){const gap=(avg/target-1)*100;if(gap>10)messages.push('Projet dépassé de plus de 10 % : malus d’un point sur cette course.');else if(gap>=-2)messages.push('Vitesse moyenne conforme au projet : 2/2 pour cette course.');else if(gap>=-5)messages.push('Vitesse légèrement sous la cible : 1,5/2 pour cette course.');else if(gap>=-8)messages.push('Vitesse sous la cible : 1/2 pour cette course.');else messages.push('Écart négatif important au projet : travailler la gestion de l’allure.');}
 const early=limit<r.duration*60000;
 return <div className="pedagogy"><div className="pedagogy-heading"><h3>Analyse pédagogique automatique</h3><span className="pedagogy-tag">{r.duration} min</span></div><ul>{messages.map((m,i)=><li key={i}>{m}</li>)}</ul><p className="pedagogy-goal"><strong>Objectif pour la prochaine course :</strong> {variation!==null&&variation>6?'réduire les variations de vitesse entre les tours.':target&&avg<target*.95?'se rapprocher davantage de la vitesse cible dès les premiers tours.':trend< -5?'maintenir la même allure jusqu’aux derniers tours.':'reproduire une allure stable et proche du projet.'}</p>{early&&<p className="muted">Course interrompue avant la durée prévue : interpréter les résultats en tenant compte de cette interruption.</p>}<p className="muted">Analyse indicative fondée sur les tours complets de 200 m, sans diagnostic sur les capacités de l’élève. Repères de l’évaluation : régularité (CV) ≤ 2 % : 3 pts ; ≤ 4 % : 2,5 ; ≤ 6 % : 2 ; ≤ 8 % : 1,5 ; ≤ 10 % : 1 ; ≤ 15 % : 0,5. Respect du projet : jusqu’à +10 % sans malus ; au-delà, −1 pt par course. La note de régularité finale utilise la moyenne des CV des deux courses.</p></div>;
}
function ComparisonAnalysis({pair}){
 if(pair.length!==2||pair.some(d=>d.points.length<2))return null;
 const [long,short]=pair;
 const diff=short.avg-long.avg;
 const cvLong=long.variation,cvShort=short.variation;
 const parts=[`Sur 6 minutes, la vitesse moyenne est ${Math.abs(diff)<0.05?'pratiquement identique à':diff>0?'supérieure de '+rnd(diff)+' km/h à':'inférieure de '+rnd(-diff)+' km/h à'} celle de la course de 12 minutes.`];
 if(cvLong!==null&&cvShort!==null)parts.push(Math.abs(cvShort-cvLong)<1?'La régularité est comparable sur les deux durées.':cvShort<cvLong?'La course de 6 minutes présente des vitesses au tour plus régulières.':'La course de 12 minutes présente des vitesses au tour plus régulières.');
 parts.push('Les vitesses cibles étant différentes, il faut aussi comparer chaque course à son propre projet.');
 return <div className="pedagogy comparison-analysis"><h3>Lecture pédagogique des deux courses</h3>{parts.map((t,i)=><p key={i}>{t}</p>)}</div>;
}
function StudentReport({student,races,records,sessionId,raceEnds,onEdit}){
 const reports=races.filter(r=>r.group===student.group).map(r=>{
  const rec=records[`${sessionId}:${r.id}:${student.id}`]||{laps:[],marker:0};
  const limit=raceEnds[`${sessionId}:${r.id}`]??r.duration*60000;
  const target=targetFor(student,r.duration);
  const points=(rec.laps||[]).map((t,i)=>({tour:i+1,x:i+1,v:speed(200,t-(rec.laps[i-1]||0)),progress:limit>0?t/limit*100:0})).filter(p=>Number.isFinite(p.v)&&p.v>0);
  const distance=rec.laps.length*200+(Number(rec.marker)||0);
  const avg=speed(distance,limit),deviations=target?points.map(p=>Math.abs(p.v/target-1)*100):[];
  const mean=points.length?points.reduce((a,p)=>a+p.v,0)/points.length:0;
  const variation=mean?Math.sqrt(points.reduce((a,p)=>a+(p.v-mean)**2,0)/points.length)/mean*100:null;
  return {r,rec,limit,target,points,distance,avg,variation,projectDeviation:deviations.length?deviations.reduce((a,b)=>a+b,0)/deviations.length:null};
 });
 const pair=[reports.find(x=>x.r.duration===12),reports.find(x=>x.r.duration===6)].filter(Boolean);
 return <div className="panel report-panel"><div className="heading"><div><h2>Bilan individuel — {student.first} {student.last}</h2><p className="muted">Groupe {student.group} · Les graphiques se mettent à jour après chaque correction.</p></div></div>
 {reports.length===0&&<p className="muted">Aucune course prévue pour cet élève dans cette séance.</p>}
 {reports.map((d,i)=><section className="report-race" key={d.r.id}><div className="heading"><h2>Course de {d.r.duration} minutes · {d.r.group}</h2><button className="secondary" onClick={()=>onEdit(d.r,student)}>Modifier les passages</button></div>
 <div className="report-stats"><div><small>Distance totale</small><strong>{d.distance} m</strong></div><div><small>Vitesse moyenne</small><strong>{rnd(d.avg)} km/h</strong></div><div><small>Vitesse cible</small><strong>{rnd(d.target)} km/h</strong></div><div><small>Écart à la vitesse cible</small><strong>{d.target?`${d.avg>=d.target?'+':''}${rnd((d.avg/d.target-1)*100)} %`:'—'}</strong></div><div><small>Régularité (CV)</small><strong>{d.variation===null?'—':rnd(d.variation)+' %'}</strong></div><div><small>Écart moyen par tour à la cible</small><strong>{d.projectDeviation===null?'—':rnd(d.projectDeviation)+' %'}</strong></div></div>
 <h3>Évolution de la vitesse par tour</h3><VelocityChart series={[{label:`${d.r.duration} min`,points:d.points,target:d.target}]}/><PedagogicalAnalysis report={d}/>
 </section>)}
 {pair.length===2&&<section className="report-race"><h2>Comparaison des courses de 12 et 6 minutes</h2><p className="muted">Les deux courses ont des durées différentes : la comparaison utilise leur progression en pourcentage du temps écoulé. Chaque point représente la vitesse du dernier tour complet à cet instant.</p><VelocityChart mode="progress" series={pair.map(d=>({label:`${d.r.duration} min`,target:d.target,points:d.points.map(p=>({...p,x:Math.min(100,p.progress)}))}))}/><div className="tablewrap"><table><thead><tr><th>Indicateur</th><th>12 minutes</th><th>6 minutes</th></tr></thead><tbody>{[['Distance',d=>d.distance+' m'],['Vitesse moyenne',d=>rnd(d.avg)+' km/h'],['Vitesse cible',d=>rnd(d.target)+' km/h'],['Régularité (CV)',d=>d.variation===null?'—':rnd(d.variation)+' %'],['Écart moyen par tour à la cible',d=>d.projectDeviation===null?'—':rnd(d.projectDeviation)+' %']].map(([label,fn])=><tr key={label}><td>{label}</td>{pair.map(d=><td key={d.r.id}>{fn(d)}</td>)}</tr>)}</tbody></table></div><div className="combined-summary"><h3>Synthèse des deux courses</h3>{(()=>{const distance=pair.reduce((n,d)=>n+d.distance,0),duration=pair.reduce((n,d)=>n+d.limit,0),target=pair.reduce((n,d)=>n+d.target*d.limit,0)/duration,cv=pair.every(d=>d.variation!==null)?pair.reduce((n,d)=>n+d.variation,0)/2:null,gaps=pair.every(d=>d.target>0)?pair.reduce((n,d)=>n+(d.avg/d.target-1)*100,0)/2:null;return <div className="combined-stats">{[['Distance totale',distance+' m'],['Vitesse moyenne totale',rnd(speed(distance,duration))+' km/h'],['Vitesse cible moyenne',rnd(target)+' km/h'],['Régularité moyenne',cv===null?'—':rnd(cv)+' %'],['Écart moyen des deux courses à leur cible',gaps===null?'—':(gaps>=0?'+':'')+rnd(gaps)+' %']].map(([name,val])=><div key={name}><small>{name}</small><strong>{val}</strong></div>)}</div>})()}<p className="muted">Vitesse cible moyenne pondérée par la durée ; régularité = moyenne des deux CV ; écart moyen des deux courses = moyenne des écarts finaux signés, distincte de l’écart moyen par tour à la cible. Le respect du projet est noté séparément sur chaque course.</p></div><ComparisonAnalysis pair={pair}/></section>}
 <p className="muted">CV = coefficient de variation des vitesses sur les tours complets (plus faible = plus régulier). Le dernier repère de 25 m compte dans la distance et la vitesse moyenne finales, mais pas dans la courbe des tours complets.</p></div>
}

const parsePace=x=>({verte:'V',vert:'V',orange:'O',rouge:'R',noire:'N',noir:'N',v:'V',o:'O',r:'R',n:'N'})[String(x||'').trim().toLowerCase()]||'';
const PACES=[{id:'V',label:'Verte',offset:3,color:'#269b60'},{id:'O',label:'Orange',offset:2,color:'#ee9b35'},{id:'R',label:'Rouge',offset:1,color:'#dc5656'},{id:'N',label:'Noire',offset:0,color:'#252b37'}];
const paceById=id=>PACES.find(p=>p.id===id);
function targetFor(student,duration){const pace=paceById(duration===12?student.pace12:student.pace6),vma=Number(student.vma);return pace?(vma>pace.offset?vma-pace.offset:0):Number(duration===12?student.target12:student.target6)||0;}
function projectChoiceScore(student){const a=paceById(student.pace12),b=paceById(student.pace6);if(!a||!b||!(Number(student.vma)>0))return null;if(a.id===b.id)return 0;if(a.id==='O'&&['R','N'].includes(b.id))return 4;if(a.id==='V'&&['O','R'].includes(b.id))return 3;if(a.id==='V'&&b.id==='N')return 2;if(a.id==='R'&&b.id==='N')return 2;if(a.offset<b.offset)return 1;return null;}
function projectCourseScore(actual,target){if(!(target>0))return null;const diff=(actual/target-1)*100;return diff>10?1:diff>=-2?2:diff>=-5?1.5:diff>=-8?1:diff>=-10?.5:0;}
const CRITERIA=[['performance','Vitesse moyenne',6],['project','Respect du projet',4],['regularity','Régularité',3],['choice','Cohérence du projet',4],['coach','Observateur-coach',3]];
const roundHalf=x=>Math.round(x*2)/2;
const clamp=(v,lo,hi)=>Math.min(hi,Math.max(lo,v));
function scoreThreshold(x){return x<=2?3:x<=4?2.5:x<=6?2:x<=8?1.5:x<=10?1:x<=15?.5:0}
function evaluateStudent(student,session,records,raceEnds,coachEntries={},classStudents=[]){
 const races=(session?.races||[]).filter(r=>r.group===student.group);
 const find=duration=>{const r=races.find(r=>r.duration===duration);if(!r)return null;const rec=records[`${session.id}:${r.id}:${student.id}`];if(!rec||!((rec.laps||[]).length||Number(rec.marker)))return null;const limit=raceEnds[`${session.id}:${r.id}`]??r.duration*60000;if(limit<=0)return null;const dist=(rec.laps||[]).length*200+(Number(rec.marker)||0),v=speed(dist,limit),target=targetFor(student,duration);const vs=(rec.laps||[]).map((t,i)=>speed(200,t-((rec.laps||[])[i-1]||0))).filter(x=>Number.isFinite(x)&&x>0);const mean=vs.reduce((a,b)=>a+b,0)/(vs.length||1);const cv=vs.length>=2&&mean?Math.sqrt(vs.reduce((a,b)=>a+(b-mean)**2,0)/vs.length)/mean*100:null;return {v,target,cv,dist,limit,r}};
 const a=find(12),b=find(6),vma=Number(student.vma),sex=student.sex;
 const result={performance:null,project:null,regularity:null,choice:projectChoiceScore(student),coach:null};
 if(a&&b&&['F','G'].includes(sex)){const avg=(a.dist+b.dist)/((a.limit+b.limit)/3600000)/1000;result.performance=roundHalf(clamp((avg-(sex==='G'?9:8))/5*6,0,6));}
 if(a&&b&&a.target>0&&b.target>0)result.project=projectCourseScore(a.v,a.target)+projectCourseScore(b.v,b.target);
 if(a&&b&&a.cv!==null&&b.cv!==null)result.regularity=scoreThreshold((a.cv+b.cv)/2);
 result.coach=coachGrade(student.id,session,classStudents,records,coachEntries)?.score??null;
 return result;
}
function evaluationMeasurements(student,session,records,raceEnds){
 const races=(session?.races||[]).filter(r=>r.group===student.group);
 const one=duration=>{const r=races.find(x=>x.duration===duration);if(!r)return null;
 const rec=records[`${session.id}:${r.id}:${student.id}`];if(!rec||!((rec.laps||[]).length||Number(rec.marker)))return null;
 const limit=raceEnds[`${session.id}:${r.id}`]??r.duration*60000;
 if(limit<=0)return null;
 const dist=(rec.laps||[]).length*200+(Number(rec.marker)||0),v=speed(dist,limit),target=targetFor(student,duration);
 const laps=(rec.laps||[]).map((t,i)=>speed(200,t-((rec.laps||[])[i-1]||0))).filter(x=>Number.isFinite(x)&&x>0);
 const mean=laps.length?laps.reduce((a,b)=>a+b,0)/laps.length:0;
 const cv=laps.length>=2&&mean>0?Math.sqrt(laps.reduce((a,b)=>a+(b-mean)**2,0)/laps.length)/mean*100:null;
 return {v,target,cv,dist,limit,pace:paceById(duration===12?student.pace12:student.pace6)};
 };
 const a=one(12),b=one(6);
 const fmtDelta=d=>d===null?'—':`${d>=0?'+':''}${rnd(d)} %`;
 const deviation=d=>d&&d.target>0?(d.v/d.target-1)*100:null;
 const avg=a&&b?speed(a.dist+b.dist,a.limit+b.limit):null;
 const regularity=a&&b&&a.cv!==null&&b.cv!==null?(a.cv+b.cv)/2:null;
 const fmtCourse=(d,duration)=>d?`${duration} min : ${rnd(d.v)} km/h / cible ${d.target>0?rnd(d.target)+' km/h':'—'} (${fmtDelta(deviation(d))})`:`${duration} min : données manquantes`;
 const labelPace=(id)=>paceById(id)?.label||'Non définie';
 return {
 performance:avg===null?'Deux courses nécessaires':`Moyenne pondérée : ${rnd(avg)} km/h · 12 min : ${rnd(a.v)} · 6 min : ${rnd(b.v)} km/h`,
 project:`${fmtCourse(a,12)} | ${fmtCourse(b,6)}`,
 regularity:regularity===null?`12 min : ${a?.cv===null||!a?'—':rnd(a.cv)+' %'} · 6 min : ${b?.cv===null||!b?'—':rnd(b.cv)+' %'} (2 tours complets minimum)`:`CV moyen : ${rnd(regularity)} % · 12 min : ${rnd(a.cv)} % · 6 min : ${rnd(b.cv)} %`,
 choice:`12 min : ${labelPace(student.pace12)} (${targetFor(student,12)>0?rnd(targetFor(student,12))+' km/h':'—'}) · 6 min : ${labelPace(student.pace6)} (${targetFor(student,6)>0?rnd(targetFor(student,6))+' km/h':'—'}) · VMA : ${Number(student.vma)>0?rnd(student.vma)+' km/h':'non renseignée'}`,
 coach:'Appréciation et note attribuées par l’enseignant'
 };
}

// Une ligne par coach et par séance : le coach est évalué, pas son coureur.
function coachDistance(student,session,records){
 if(!student||!session)return null;
 const rs=[12,6].map(duration=>session.races.find(r=>r.duration===duration&&r.group===student.group));
 if(rs.some(r=>!r))return null;
 const recs=rs.map(r=>records[`${session.id}:${r.id}:${student.id}`]);
 if(recs.some(rec=>!rec||(!((rec.laps||[]).length)&&!(Number(rec.marker)>0))))return null;
 return recs.reduce((sum,rec)=>sum+(rec.laps||[]).length*200+(Number(rec.marker)||0),0);
}
function coachGrade(coachId,session,students,records,coachEntries){
 const entry=coachEntries?.[`${session?.id}:${coachId}`];
 if(!entry||!entry.runnerId||entry.counted===''||entry.counted===null||entry.counted===undefined)return null;
 const counted=Number(entry.counted),runner=students.find(s=>s.id===entry.runnerId);
 const actual=coachDistance(runner,session,records);
 if(!Number.isFinite(counted)||counted<0||actual===null||runner?.id===coachId)return null;
 const gap=Math.abs(counted-actual);
 const base=gap<=25?3:gap<=75?2:gap<=125?1:gap<=200?.5:0;
 const penalty=['incomplete','messy','heartRate'].filter(k=>entry[k]).length*.25;
 return {actual,counted,gap,base,penalty,score:Math.max(0,base-penalty)};
}
function CoachObserver({students,session,records,coachEntries,onChange}){
 const sorted=[...students].sort((a,b)=>a.last.localeCompare(b.last,'fr')||a.first.localeCompare(b.first,'fr'));
 const update=(id,patch)=>onChange(old=>({...old,[`${session.id}:${id}`]:{...(old[`${session.id}:${id}`]||{}),...patch}}));
 return <><div className="heading"><div><h1>Coach-observateur</h1><p className="muted">Chaque ligne correspond à l'élève évalué dans son rôle de coach. La distance réelle est la somme des courses de 12 et 6 minutes de son coureur.</p></div></div>
 <div className="panel"><div className="tablewrap"><table className="coach-table"><thead><tr><th>Coach évalué</th><th>Son coureur</th><th>Distance comptée (m)</th><th>Distance réelle (m)</th><th>Écart absolu</th><th>Note avant malus</th><th>Malus −0,25 chacun</th><th>Note finale /3</th></tr></thead><tbody>
 {sorted.map(coach=>{const entry=coachEntries[`${session.id}:${coach.id}`]||{},result=coachGrade(coach.id,session,students,records,coachEntries),runner=students.find(s=>s.id===entry.runnerId),actual=coachDistance(runner,session,records);return <tr key={coach.id}><td><strong>{coach.last} {coach.first}</strong></td><td><select aria-label={`Coureur de ${coach.first} ${coach.last}`} value={entry.runnerId||''} onChange={e=>update(coach.id,{runnerId:e.target.value})}><option value="">Choisir un coureur</option>{sorted.filter(s=>s.id!==coach.id).map(s=><option key={s.id} value={s.id}>{s.last} {s.first}</option>)}</select></td><td><input aria-label={`Distance comptée par ${coach.first} ${coach.last}`} type="number" min="0" step="25" inputMode="numeric" placeholder="Distance en m" value={entry.counted??''} onChange={e=>update(coach.id,{counted:e.target.value})}/></td><td>{actual===null?'—':`${actual} m`}</td><td>{result?`${result.gap} m`:'—'}</td><td>{result?`${result.base} / 3`:'—'}</td><td><div className="coach-checks">{[['incomplete','Fiche incomplète'],['messy','Propreté'],['heartRate','FC incohérente']].map(([k,label])=><label key={k}><input type="checkbox" checked={!!entry[k]} onChange={e=>update(coach.id,{[k]:e.target.checked})}/>{label}</label>)}</div></td><td><strong className={'coach-final '+(result?result.score>=2.25?'good':result.score>=1.5?'medium':'low':'missing')}>{result?`${result.score.toLocaleString('fr-FR')} / 3`:'À compléter'}</strong></td></tr>})}
 </tbody></table></div><p className="muted">Barème : 0–25 m = 3 pts ; plus de 25–75 m = 2 pts ; plus de 75–125 m = 1 pt ; plus de 125–200 m = 0,5 pt ; plus de 200 m = 0 pt. Les trois malus sont cumulables, sans note négative. Si une mesure manque, aucune note automatique n'est attribuée.</p><p className="muted">La note est transmise à l'évaluation individuelle et au bilan collectif. Une correction manuelle effectuée dans l'évaluation conserve la priorité ; le bouton « Revenir au calcul » rétablit la note issue de cette grille.</p></div></>;
}
const COACH_LEVELS=[{points:1,title:'Observateur débutant',description:'Observations incomplètes ou peu fiables ; conseils peu précis.'},{points:2,title:'Observateur efficace',description:'Observations globalement fiables ; suivi sérieux et conseils utiles.'},{points:3,title:'Observateur-coach autonome',description:'Observations fiables, suivi rigoureux et conseils pertinents pour ajuster l’allure.'}];
function CoachScale(){return <div className="coach-scale"><strong>Repères pour le rôle d’observateur-coach (sur 3 points)</strong><div className="coach-levels">{COACH_LEVELS.map(x=><div key={x.points} className={'coach-level coach-level-'+x.points}><b>{x.points} point{x.points>1?'s':''}</b><strong>{x.title}</strong><span>{x.description}</span></div>)}</div><small>0 point : rôle non assuré ou observations absentes. Les demi-points restent disponibles pour nuancer l’appréciation de l’enseignant.</small></div>}
function CollectiveAssessment({students,session,records,raceEnds,coachEntries,evaluations,onSelect}){
 const rows=[...students].sort((a,b)=>a.last.localeCompare(b.last,'fr')||a.first.localeCompare(b.first,'fr')).map(student=>{
 const automatic=evaluateStudent(student,session,records,raceEnds,coachEntries,students),entry=evaluations[`${session.id}:${student.id}`]||{},overrides=entry.overrides||{};
 const scores=CRITERIA.map(([key,label,max])=>({key,label,max,value:Object.prototype.hasOwnProperty.call(overrides,key)?overrides[key]:automatic[key],manual:Object.prototype.hasOwnProperty.call(overrides,key)}));
 const complete=scores.every(x=>x.value!==null&&x.value!==undefined&&Number.isFinite(Number(x.value)));
 const total=complete?scores.reduce((sum,x)=>sum+Number(x.value),0):null;
 return {student,scores,total,entry,complete};
 });
 const gradeColor=(v,max)=>v===null||v===undefined?'#a3afbb':v/max>=.8?'#27a46e':v/max>=.5?'#347bd1':v/max>=.35?'#ed9a43':'#db5c61';
 const completeRows=rows.filter(x=>x.complete),average=completeRows.length?completeRows.reduce((sum,x)=>sum+x.total,0)/completeRows.length:null;
 return <div className="panel collective-panel"><div className="heading"><div><h2>Bilan collectif de la classe</h2><p className="muted">{rows.length} élèves · {completeRows.length} évaluations complètes · {rows.filter(x=>x.entry.validated).length} validées</p></div>{average!==null&&<strong className="collective-average">Moyenne : {rnd(average)} / 20</strong>}</div>
 <p className="muted">Les couleurs représentent la proportion de points obtenus pour chaque critère : rouge (moins de 35 %), orange (35–49 %), bleu (50–79 %), vert (80–100 %). Gris = note manquante. Une note modifiée manuellement est marquée d’un astérisque (*).</p>
 <div className="tablewrap"><table className="collective-table"><thead><tr><th>Élève</th><th>Groupe</th>{CRITERIA.map(([key,label,max])=><th key={key}>{label}<small>/{max}</small></th>)}<th>Total /20</th><th>Statut</th><th>Fiche</th></tr></thead><tbody>{rows.map(({student,scores,total,entry,complete})=><tr key={student.id}><td><strong>{student.last} {student.first}</strong></td><td>{student.group}</td>{scores.map(({key,max,value,manual})=><td key={key}><span className="collective-score" style={{background:gradeColor(value,max),color:value===null||value===undefined?'#273747':max&&value/max>=.35&&value/max<.5?'#253241':'#fff'}} title={manual?'Note modifiée par l’enseignant':'Note automatique'}>{value===null||value===undefined?'—':Number(value).toLocaleString('fr-FR')}{manual?'*':''}</span></td>)}<td><strong className="collective-total" style={{color:gradeColor(total,20)}}>{total===null?'—':Number(total.toFixed(2)).toLocaleString('fr-FR')}</strong></td><td><span className={'collective-status '+(entry.validated?'validated':complete?'pending':'incomplete')}>{entry.validated?'Validée':complete?'À valider':'À compléter'}</span></td><td><button className="secondary" onClick={()=>onSelect(student.id)}>Évaluer</button></td></tr>)}</tbody></table></div>
 </div>;
}
function GradeEditor({student,session,records,raceEnds,coachEntries,classStudents,entry,onChange,onOpenReport}){
 const automatic=evaluateStudent(student,session,records,raceEnds,coachEntries,classStudents),overrides=entry?.overrides||{};
 const measurements=evaluationMeasurements(student,session,records,raceEnds);const coachResult=coachGrade(student.id,session,classStudents,records,coachEntries);measurements.coach=coachResult?`Coach : ${coachResult.counted} m · Coureur : ${coachResult.actual} m · écart : ${coachResult.gap} m · base ${coachResult.base}/3 · malus −${coachResult.penalty.toLocaleString('fr-FR')}`:'À renseigner dans l’onglet Coach-observateur (coureur et distance comptée)';
 const note=c=>Object.prototype.hasOwnProperty.call(overrides,c)?overrides[c]:automatic[c];
 const total=CRITERIA.every(([k])=>note(k)!==null)?CRITERIA.reduce((sum,[k])=>sum+note(k),0):null;
 const update=(patch)=>onChange({...entry,...patch,validated:false});
 const setOverride=(k,v)=>update({overrides:{...overrides,[k]:v}});
 const reset=(k)=>{const next={...overrides};delete next[k];update({overrides:next})};
 const gradeColor=(v,max)=>v===null?'#8c9bac':v/max>=.8?'#27a46e':v/max>=.5?'#347bd1':v/max>=.35?'#ed9a43':'#db5c61';
 return <div className="panel eval-editor"><div className="heading"><h2>{student.first} {student.last}</h2><strong className="eval-total">{total===null?'À compléter':`${Number(total.toFixed(2))} / 20`}</strong></div>
 <p className="muted">Les résultats mesurés apparaissent sous chaque critère. </p><div className="eval-report-link"><button className="secondary" onClick={onOpenReport}><BarChart3 size={17}/> Voir / masquer le bilan et les graphiques</button></div>
 <div className="tablewrap"><table><thead><tr><th>Critère et résultat mesuré</th><th>Automatique</th><th>Note retenue</th><th>Action</th></tr></thead><tbody>{CRITERIA.map(([k,label,max])=><tr key={k}><td><div className="eval-criterion"><div><span className="eval-dot" style={{background:gradeColor(note(k),max)}}/> <strong>{label} / {max}</strong></div><small className="eval-measure">{measurements[k]}</small></div></td><td>{automatic[k]===null?'—':automatic[k]}</td><td><select aria-label={`Note ${label}`} value={note(k)??''} onChange={e=>setOverride(k,e.target.value===''?null:Number(e.target.value))}><option value="">Non noté</option>{Array.from({length:max*4+1},(_,i)=>i/4).map(v=><option key={v} value={v}>{v}</option>)}</select>{Object.prototype.hasOwnProperty.call(overrides,k)&&<small className="eval-manual">Manuelle</small>}</td><td><button className="secondary" disabled={!Object.prototype.hasOwnProperty.call(overrides,k)} onClick={()=>reset(k)}>Revenir au calcul</button></td></tr>)}</tbody></table></div>
 <label>Commentaire de l'enseignant<textarea rows="3" value={entry?.comment||''} onChange={e=>update({comment:e.target.value})} placeholder="Observations, justification d'une modification…"/></label>
 <div className="eval-actions"><span className="muted">{entry?.validated?'✓ Évaluation validée':total===null?'Données ou notes manquantes':'En attente de validation'}</span><button disabled={total===null} onClick={()=>onChange({...entry,overrides,validated:true,validatedAt:new Date().toISOString()})}>Valider l'évaluation</button>{entry?.validated&&<button className="secondary" onClick={()=>update({})}>Rouvrir</button>}</div></div>;
}

function BaremeEleves(){
 const [vma,setVma]=useState(15);
 const paces=[{label:'VERTE',offset:3,color:'#269b60'},{label:'ORANGE',offset:2,color:'#ee9b35'},{label:'ROUGE',offset:1,color:'#dc5656'},{label:'NOIRE',offset:0,color:'#252b37'}];
 return <div className="bareme-page">
  <div className="heading"><div><h1>Barème de l’évaluation</h1><p className="muted">Fiche synthétique à présenter aux élèves · Deux courses : 12 minutes et 6 minutes</p></div><button className="secondary" onClick={()=>window.print()}>Imprimer / PDF</button></div>
  <div className="bareme-hero"><div><span>ÉVALUATION DEMI-FOND</span><h2>Construire son projet, courir régulièrement et accompagner un camarade</h2><p>Une note sur 20, construite à partir des résultats des deux courses et du rôle de coach.</p></div><strong>20<span>points</span></strong></div>
  <div className="bareme-grid">
   {[['Performance','6','Vitesse moyenne sur les deux courses'],['Respect du projet','4','Atteindre ou dépasser raisonnablement sa vitesse cible'],['Régularité','3','Maintenir une vitesse stable à chaque tour'],['Choix du projet','4','Choisir deux allures différentes et adaptées'],['Observateur-coach','3','Observer, relever et conseiller']].map(([name,pts,desc],i)=><div className="bareme-summary" key={name}><b className={'bareme-number n'+i}>{pts}</b><div><strong>{name}</strong><small>{desc}</small></div></div>)}
  </div>
  <section className="panel bareme-section"><h2>1. Performance — 6 points</h2><p>On utilise la vitesse moyenne globale : distance totale parcourue pendant les deux courses ÷ durée totale réelle. La note est calculée par progression linéaire et arrondie au demi-point.</p><div className="tablewrap"><table><thead><tr><th>Note repère</th><th>Garçons</th><th>Filles</th></tr></thead><tbody>{[[0,'9','8'],[1,'9,83','8,83'],[2,'10,67','9,67'],[3,'11,50','10,50'],[4,'12,33','11,33'],[5,'13,17','12,17'],[6,'14 ou plus','13 ou plus']].map((r,i)=><tr key={i}><td><b>{r[0]} / 6</b></td><td>{r[1]} km/h</td><td>{r[2]} km/h</td></tr>)}</tbody></table></div><p className="muted">En dessous de 9 km/h (garçons) ou 8 km/h (filles) : 0 point. Les valeurs intermédiaires sont calculées automatiquement.</p></section>
  <section className="panel bareme-section"><h2>2. Respect du projet — 4 points</h2><p>Chaque course est notée sur 2 points. Un élève qui dépasse sa cible de 10 % ou moins n’est pas pénalisé. Au-delà de +10 %, il reçoit un malus d’un point sur la course concernée.</p><div className="tablewrap"><table><thead><tr><th>Vitesse réalisée par rapport à la cible</th><th>Points par course</th></tr></thead><tbody>{[['De −2 % à +10 % inclus','2 / 2'],['Inférieure de plus de 2 à 5 %','1,5 / 2'],['Inférieure de plus de 5 à 8 %','1 / 2'],['Inférieure de plus de 8 à 10 %','0,5 / 2'],['Inférieure de plus de 10 %','0 / 2'],['Supérieure de plus de 10 % (malus)','1 / 2']].map((r,i)=><tr key={i}><td>{r[0]}</td><td><strong>{r[1]}</strong></td></tr>)}</tbody></table></div><p className="muted">Exemple : 2 points en 12 min + 1,5 point en 6 min = 3,5 / 4.</p></section>
  <section className="panel bareme-section"><h2>3. Régularité — 3 points</h2><p>On compare les vitesses de chaque tour complet de 200 m. Plus le coefficient de variation (CV) est faible, plus l’allure est régulière. Le score repose sur la moyenne des CV des deux courses.</p><div className="tablewrap"><table><thead><tr><th>CV moyen des deux courses</th><th>Note</th></tr></thead><tbody>{[['Jusqu’à 2 %','3'],['Plus de 2 à 4 %','2,5'],['Plus de 4 à 6 %','2'],['Plus de 6 à 8 %','1,5'],['Plus de 8 à 10 %','1'],['Plus de 10 à 15 %','0,5'],['Plus de 15 %','0']].map((r,i)=><tr key={i}><td>{r[0]}</td><td><strong>{r[1]} / 3</strong></td></tr>)}</tbody></table></div><p className="muted">Deux tours complets au minimum par course sont nécessaires pour calculer ce critère.</p></section>
  <section className="panel bareme-section"><h2>4. Cohérence du projet — 4 points</h2><p>Chaque élève choisit une allure différente pour la course de 12 minutes et celle de 6 minutes. Les vitesses sont calculées à partir de sa VMA.</p><div className="bareme-vma"><label>Exemple de VMA (km/h) <input type="number" min="4" max="30" step="0.5" value={vma} onChange={e=>setVma(Number(e.target.value))}/></label><div className="bareme-paces">{paces.map(x=><div key={x.label} className="bareme-pace" style={{borderColor:x.color}}><span style={{background:x.color,color:'white'}}>{x.label}</span><b>VMA − {x.offset}</b><strong>{Number.isFinite(vma)?(vma-x.offset).toLocaleString('fr-FR'):'—'} km/h</strong></div>)}</div></div><div className="tablewrap"><table><thead><tr><th>Allure 12 minutes</th><th>Allure 6 minutes</th><th>Note</th></tr></thead><tbody>{[['Orange','Rouge ou Noire','4'],['Verte','Orange ou Rouge','3'],['Verte','Noire','2'],['Rouge','Noire','2'],['Allure 12 min plus rapide','Allure 6 min moins rapide','1'],['Deux allures identiques','Choix non respecté','0']].map((r,i)=><tr key={i}><td>{r[0]}</td><td>{r[1]}</td><td><strong>{r[2]} / 4</strong></td></tr>)}</tbody></table></div><p className="muted">Les autres combinaisons non prévues dans cette grille restent à apprécier par l’enseignant.</p></section>
  <section className="panel bareme-section"><h2>5. Observateur-coach — 3 points</h2><p>Le coach note la distance cumulée des deux courses de son coureur. On compare cette distance à la distance réellement parcourue, sans tenir compte du signe de l’écart.</p><div className="tablewrap"><table><thead><tr><th>Écart absolu entre les distances</th><th>Note de départ</th></tr></thead><tbody>{[['0 à 25 m','3'],['Plus de 25 à 75 m','2'],['Plus de 75 à 125 m','1'],['Plus de 125 à 200 m','0,5'],['Plus de 200 m','0']].map(([range,n])=><tr key={range}><td>{range}</td><td><strong>{n} / 3</strong></td></tr>)}</tbody></table></div><h3>Malus cumulables</h3><p>−0,25 point pour chacun des éléments suivants : fiche incomplète ; manque de propreté ; fréquence cardiaque incohérente.</p><p className="muted">La note finale ne peut pas être négative. L’enseignant peut la modifier manuellement dans l’évaluation.</p></section>
  <section className="panel bareme-section technical-details"><h2>Détail technique — comprendre les indicateurs</h2>
  <h3>1. Écart à la vitesse cible</h3><p>Il compare la vitesse moyenne réellement obtenue sur <strong>toute la course</strong> avec la vitesse cible choisie. Il peut être négatif (moins vite) ou positif (plus vite). C’est cet indicateur qui sert à noter le <strong>respect du projet sur 4 points</strong> (2 points par course).</p><p><strong>Exemple :</strong> cible 12 km/h, vitesse moyenne réelle 11,4 km/h : (11,4 ÷ 12 − 1) × 100 = <strong>−5 %</strong>.</p>
  <h3>2. Écart moyen par tour à la cible</h3><p>Pour chaque tour complet de 200 m, on calcule la différence avec la cible, <strong>sans tenir compte du signe</strong>, puis on fait la moyenne. Les tours trop rapides et trop lents ne s’annulent pas. C’est un repère pédagogique complémentaire, différent de la note de régularité.</p><p><strong>Exemple :</strong> cible 12 km/h ; tours à 11, 12 et 13 km/h : écarts absolus 8,33 %, 0 % et 8,33 % ; moyenne = <strong>5,56 %</strong>.</p>
  <h3>3. Coefficient de variation (CV) — la régularité</h3><p>Le CV mesure les variations de vitesse entre les tours, <strong>par rapport à la moyenne des vitesses de ces tours</strong>, et non par rapport au projet. Plus il est petit, plus l’allure est stable. Formule : <strong>CV = écart-type des vitesses ÷ moyenne des vitesses × 100</strong>. Il sert à noter la régularité sur 3 points.</p>
  <p><strong>Exemple :</strong> vitesses de 11, 12 et 13 km/h ; moyenne des vitesses = 12 km/h ; écart-type ≈ 0,82 km/h ; CV ≈ <strong>6,8 %</strong>.</p>
  <h3>4. Trois élèves, même cible de 12 km/h</h3><p>Chaque point du graphique représente un tour complet de 200 m. Les trois élèves ont la même vitesse cible, mais des stratégies très différentes.</p>
  <VelocityChart series={[{label:'Élève A',target:12,points:[12,12,12,12].map((v,i)=>({x:i+1,tour:i+1,v}))},{label:'Élève B',target:12,points:[10,10,10,10].map((v,i)=>({x:i+1,tour:i+1,v}))},{label:'Élève C',target:12,points:[10,14,12,12].map((v,i)=>({x:i+1,tour:i+1,v}))}]}/>
  <div className="tablewrap"><table><thead><tr><th>Élève</th><th>Vitesses par tour</th><th>CV</th><th>Écart moyen par tour à la cible</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>12 · 12 · 12 · 12</td><td>0 %</td><td>0 %</td></tr><tr><td><strong>B</strong></td><td>10 · 10 · 10 · 10</td><td>0 %</td><td>16,7 %</td></tr><tr><td><strong>C</strong></td><td>10 · 14 · 12 · 12</td><td>11,8 %</td><td>8,3 %</td></tr></tbody></table></div>
  <p><strong>Élève A :</strong> régulier et à la bonne vitesse. <strong>Élève B :</strong> très régulier, mais trop lent par rapport au projet. <strong>Élève C :</strong> vitesse variable malgré une moyenne des vitesses par tour égale à la cible.</p><p className="muted">Attention : la moyenne arithmétique des vitesses de tours de 200 m n’est pas nécessairement la vitesse moyenne de toute la course. Cette dernière est calculée avec la distance totale et le temps total.</p>
  </section>
  <div className="bareme-note"><strong>À retenir</strong><p>Les notes automatiques sont des propositions. L’enseignant peut corriger chaque critère, justifier son choix et valider la note finale.</p></div>
 </div>
}


function PrintableStudentSheets({students,session,records,raceEnds,coachEntries,evaluations}){
 if(!session)return null;
 return <div className="print-all-students">{students.map(st=>{
  const automatic=evaluateStudent(st,session,records,raceEnds,coachEntries,students);
  const entry=evaluations[`${session.id}:${st.id}`]||{};
  const overrides=entry.overrides||{};
  const measure=evaluationMeasurements(st,session,records,raceEnds);
  const coach=coachGrade(st.id,session,students,records,coachEntries);
  measure.coach=coach?`Distance comptée ${coach.counted} m ; distance réelle ${coach.actual} m ; écart ${coach.gap} m ; malus −${coach.penalty.toLocaleString('fr-FR')} pt`:'Non renseigné';
  const retained=k=>Object.prototype.hasOwnProperty.call(overrides,k)?overrides[k]:automatic[k];
  const complete=CRITERIA.every(([k])=>retained(k)!==null);
  const total=complete?CRITERIA.reduce((sum,[k])=>sum+retained(k),0):null;
  return <section className="print-student-sheet" key={st.id}>
   <div className="print-sheet-header"><div><h1>Demi-fond Troisième</h1><h2>{st.first} {st.last}</h2><p>{session.name} · Groupe {st.group} · VMA {st.vma||'—'} km/h</p></div><div className="print-score">{total===null?'À compléter':`${rnd(total)} / 20`}</div></div>
   <h3>Évaluation et résultats mesurés</h3>
   <table className="print-student-table"><thead><tr><th>Critère</th><th>Résultats mesurés</th><th>Note retenue</th></tr></thead><tbody>{CRITERIA.map(([k,label,max])=><tr key={k}><td><strong>{label}</strong></td><td>{measure[k]}</td><td className="print-grade">{retained(k)===null?'—':`${retained(k)} / ${max}`}</td></tr>)}</tbody></table>
   {entry.comment&&<div className="print-comment"><strong>Appréciation de l'enseignant</strong><p>{entry.comment}</p></div>}
   <p className="print-status">{entry.validated?'Évaluation validée':'Évaluation non validée'}</p>
  </section>;
 })}</div>
}

const Button=({children,onClick,secondary=false,disabled=false})=><button type="button" className={secondary?'secondary':''} onClick={onClick} disabled={disabled}>{children}</button>;
function App(){const[classes,setClasses]=useState(()=>load('eps_classes',[{id:'demo',name:'Classe de démonstration',students:demo}]));const[classId,setClassId]=useState(()=>load('eps_classid','demo'));const[sessions,setSessions]=useState(()=>load('eps_sessions',[]));const[sessionId,setSessionId]=useState(()=>load('eps_sessionid',null));const[tab,setTab]=useState('course');const[evaluations,setEvaluations]=useState(()=>load('eps_evaluations',{}));const[evalStudentId,setEvalStudentId]=useState('');const[coachEntries,setCoachEntries]=useState(()=>load('eps_coach_entries',{}));const[reportStudentId,setReportStudentId]=useState('');const[evalReportOpen,setEvalReportOpen]=useState(false);const[printMode,setPrintMode]=useState('class');const[view,setView]=useState('cards');const[courseSort,setCourseSort]=useState('speed');const[records,setRecords]=useState(()=>load('eps_records',{}));const[raceId,setRaceId]=useState('r1');const[status,setStatus]=useState('idle');const[elapsed,setElapsed]=useState(0);const[marker,setMarker]=useState({});const[editStudent,setEditStudent]=useState(null);const[manualTime,setManualTime]=useState('');const[editIndex,setEditIndex]=useState(-1);const[raceEnds,setRaceEnds]=useState(()=>load('eps_race_ends',{}));const[startedAt,setStartedAt]=useState(null);const startRef=useRef(null),elapsedRef=useRef(0),recordsRef=useRef(records),audioRef=useRef(null),statusRef=useRef(status);useEffect(()=>{recordsRef.current=records},[records]);useEffect(()=>{statusRef.current=status},[status]);useEffect(()=>localStorage.setItem('eps_evaluations',JSON.stringify(evaluations)),[evaluations]);useEffect(()=>localStorage.setItem('eps_coach_entries',JSON.stringify(coachEntries)),[coachEntries]);useEffect(()=>localStorage.setItem('eps_classes',JSON.stringify(classes)),[classes]);useEffect(()=>localStorage.setItem('eps_classid',JSON.stringify(classId)),[classId]);useEffect(()=>localStorage.setItem('eps_sessions',JSON.stringify(sessions)),[sessions]);useEffect(()=>localStorage.setItem('eps_sessionid',JSON.stringify(sessionId)),[sessionId]);useEffect(()=>localStorage.setItem('eps_records',JSON.stringify(records)),[records]);useEffect(()=>localStorage.setItem('eps_race_ends',JSON.stringify(raceEnds)),[raceEnds]);const cls=classes.find(c=>c.id===classId)||classes[0];const session=sessions.find(s=>s.id===sessionId);const races=session?.races||initialRaces;const race=races.find(r=>r.id===raceId)||races[0];const students=(cls?.students||[]).filter(s=>s.group===race?.group);const key=(sid,rid)=>`${sessionId||'demo'}:${rid}:${sid}`;const getRec=(sid,rid=race.id)=>records[key(sid,rid)]||{laps:[],marker:0};const maxMs=(race?.duration||12)*60000;const canPoint=status==='running';const sortedStudents=[...students].sort((a,b)=>courseSort==='speed'?(targetFor(b,race.duration)-targetFor(a,race.duration))||(a.last||'').localeCompare(b.last||'','fr'):(a.last||'').localeCompare(b.last||'','fr'));
useEffect(()=>{if(!sessionId&&sessions.length)setSessionId(sessions[0].id)},[sessions,sessionId]);useEffect(()=>{if(!races.some(r=>r.id===raceId))setRaceId(races[0].id)},[sessionId]);
function beep(){try{const ctx=audioRef.current||new(window.AudioContext||window.webkitAudioContext)();audioRef.current=ctx;ctx.resume();for(let i=0;i<3;i++){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.connect(gain);gain.connect(ctx.destination);osc.frequency.value=850;gain.gain.value=.15;osc.start(ctx.currentTime+i*.3);osc.stop(ctx.currentTime+i*.3+.2)}}catch{}}
function stop(finalTime,early=false){if(statusRef.current!=='running')return;const t=Math.min(maxMs,Math.max(0,Math.round(finalTime)));elapsedRef.current=t;setElapsed(t);statusRef.current='finished';setStatus('finished');setRaceEnds(old=>({...old,[`${sessionId}:${race.id}`]:t}));startRef.current=null;beep();if(early)setTab('course')}
useEffect(()=>{if(status!=='running')return;let raf,lastPaint=-Infinity;const tick=()=>{if(statusRef.current!=='running'||startRef.current===null)return;const ms=Math.max(0,performance.now()-startRef.current);if(ms>=maxMs){stop(maxMs);return}elapsedRef.current=ms;if(ms-lastPaint>=100){lastPaint=ms;setElapsed(ms)}raf=requestAnimationFrame(tick)};raf=requestAnimationFrame(tick);return()=>cancelAnimationFrame(raf)},[status,maxMs]);
function start(){if(!session){alert('Crée d’abord une séance dans l’onglet Séances.');setTab('seances');return}if(status==='finished'&&!confirm('Recommencer cette course et effacer les passages enregistrés ?'))return;if(status==='finished'){setRaceEnds(old=>{const next={...old};delete next[`${sessionId}:${race.id}`];return next});setRecords(old=>{const next={...old};students.forEach(s=>delete next[key(s.id,race.id)]);return next})}try{const ctx=audioRef.current||new(window.AudioContext||window.webkitAudioContext)();audioRef.current=ctx;ctx.resume().catch(()=>{})}catch{}startRef.current=performance.now();elapsedRef.current=0;setElapsed(0);setMarker({});setStartedAt(Date.now());statusRef.current='running';setStatus('running')}
function point(s){if(statusRef.current!=='running'||startRef.current===null)return;const now=Math.min(maxMs,Math.max(0,performance.now()-startRef.current));setRecords(old=>{const k=key(s.id,race.id),rec=old[k]||{laps:[],marker:0};return {...old,[k]:{...rec,laps:[...rec.laps,Math.round(now)]}}})}
function undo(s){if(status==='running'||status==='finished')setRecords(old=>{const k=key(s.id,race.id),rec=old[k]||{laps:[],marker:0};return {...old,[k]:{...rec,laps:rec.laps.slice(0,-1)}}})}
function parsePassage(value){const raw=String(value).trim().replace(',', '.');const m=raw.match(/^(\d{1,2})[.:]([0-5]\d)$/);if(!m)return null;return (Number(m[1])*60+Number(m[2]))*1000}
function formatPassage(ms){const seconds=Math.floor(ms/1000);return `${Math.floor(seconds/60)}.${String(seconds%60).padStart(2,'0')}`}
function savePassage(s,index){const ms=parsePassage(manualTime),limit=raceEnds[`${sessionId}:${race.id}`]??maxMs;if(ms===null||ms<=0||ms>limit){alert('Saisis un temps en minutes.secondes (ex. 1.10) ou minutes:secondes, inférieur à la durée réelle de la course.');return}const rec=getRec(s.id);const next=[...rec.laps];if(index>=0)next[index]=ms;else next.push(ms);next.sort((a,b)=>a-b);if(next.some((t,i)=>i>0&&t<=next[i-1])){alert('Deux passages ne peuvent pas avoir exactement le même temps.');return}setRecords(old=>({...old,[key(s.id,race.id)]:{...rec,laps:next}}));setManualTime('');setEditIndex(-1)}
function deletePassage(s,index){if(!confirm('Supprimer ce passage ? La distance et les vitesses seront recalculées.'))return;const rec=getRec(s.id);setRecords(old=>({...old,[key(s.id,race.id)]:{...rec,laps:rec.laps.filter((_,i)=>i!==index)}}));setEditIndex(-1)}
function setFinalMarker(s,v){setRecords(old=>{const k=key(s.id,race.id),rec=old[k]||{laps:[],marker:0};return {...old,[k]:{...rec,marker:Number(v)}}})}
function updateStudent(id,field,value){setClasses(old=>old.map(c=>c.id!==classId?c:{...c,students:c.students.map(s=>s.id!==id?s:{...s,[field]:value})}))}
function removeRace(id){if(statusRef.current==='running'){alert('Termine la course en cours avant de supprimer une course.');return}if(!session||session.races.length<=1){alert('Une séance doit conserver au moins une course.');return}const remaining=session.races.filter(r=>r.id!==id);if(remaining.length===session.races.length)return;if(!confirm('Supprimer cette course et tous ses résultats ? Cette action est définitive.'))return;const prefix=session.id+':'+id;setSessions(old=>old.map(s=>s.id===session.id?{...s,races:s.races.filter(r=>r.id!==id)}:s));setRecords(old=>Object.fromEntries(Object.entries(old).filter(([k])=>!k.startsWith(prefix+':'))));setRaceEnds(old=>Object.fromEntries(Object.entries(old).filter(([k])=>k!==prefix)));if(race?.id===id)selectRace(remaining[0].id)}
function addSession(){const id=crypto.randomUUID();setSessions(old=>[{id,classId,name:`Séance du ${new Date().toLocaleDateString('fr-FR')}`,date:new Date().toISOString().slice(0,10),races:initialRaces.map(r=>({...r,id:crypto.randomUUID()}))},...old]);setSessionId(id);setRaceId(initialRaces[0].id);setTab('course');setStatus('idle');setElapsed(0)}
function selectRace(id){if(status==='running'){alert('Termine la course en cours avant de changer.');return}setRaceId(id);const selected=races.find(r=>r.id===id);const end=raceEnds[`${sessionId}:${id}`];const hasResults=Object.keys(records).some(k=>k.startsWith(`${sessionId}:${id}:`));const finished=end!=null||hasResults;setStatus(finished?'finished':'idle');setElapsed(finished?(end??(selected?.duration||12)*60000):0);setEditStudent(null);setEditIndex(-1);setManualTime('')}
function editFromBilans(r,s){if(status==='running'){alert('Termine la course en cours avant de modifier les passages.');return}setRaceId(r.id);setStatus('finished');setElapsed(raceEnds[`${sessionId}:${r.id}`]??r.duration*60000);setEditStudent(s.id);setEditIndex(-1);setManualTime('');setTab('course')}
async function importExcel(e){const file=e.target.files?.[0];if(!file)return;try{const data=await file.arrayBuffer(),book=XLSX.read(data),rows=XLSX.utils.sheet_to_json(book.Sheets[book.SheetNames[0]],{defval:''});const pick=(row,names)=>{const k=Object.keys(row).find(k=>names.includes(k.toLowerCase().trim()));return k?String(row[k]).trim():''};const imported=rows.map(r=>({sex:pick(r,['sexe','sex']).toUpperCase().startsWith('F')?'F':pick(r,['sexe','sex']).toUpperCase().startsWith('G')?'G':'',vma:Number(pick(r,['vma']))||0,id:crypto.randomUUID(),last:pick(r,['nom','noms','name','last']),first:pick(r,['prénom','prenom','prénoms','prenoms','first','firstname']),group:(pick(r,['groupe','group']).toUpperCase()==='B'?'B':'A'),target12:Number(pick(r,['vitesse 12','vitesse12','cible12']))||10,target6:Number(pick(r,['vitesse 6','vitesse6','cible6']))||11,pace12:parsePace(pick(r,['allure12','allure 12','projet12','projet 12'])),pace6:parsePace(pick(r,['allure6','allure 6','projet6','projet 6']))})).filter(s=>s.last||s.first);if(!imported.length)throw Error('Colonnes Nom et Prénom introuvables');const id=crypto.randomUUID();setClasses(old=>[...old,{id,name:file.name.replace(/\.xlsx?$/i,''),students:imported}]);setClassId(id);setSessionId(null);setStatus('idle');alert(`${imported.length} élèves importés.`)}catch(err){alert('Import impossible : '+err.message)}e.target.value=''}
async function importSimulation(e){const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());if(data.format!=='eps-regularite-simulation-v1'||!data.class?.students?.length||!data.session?.races?.length||!data.records)throw Error('Fichier de simulation non reconnu');if(status==='running')throw Error('Termine la course en cours avant de charger une simulation');const suffix=crypto.randomUUID(),cid='sim-classe-'+suffix,sid='sim-session-'+suffix;const mapping={};const importedStudents=data.class.students.map(s=>{const id=crypto.randomUUID();mapping[s.id]=id;return {...s,id}});const raceMapping={};const importedRaces=data.session.races.map(r=>{const id=crypto.randomUUID();raceMapping[r.id]=id;return {...r,id}});const newRecords={};for(const [oldKey,rec] of Object.entries(data.records)){const parts=oldKey.split(':');const oldRace=parts[1],oldStudent=parts[2];if(raceMapping[oldRace]&&mapping[oldStudent])newRecords[`${sid}:${raceMapping[oldRace]}:${mapping[oldStudent]}`]={laps:(rec.laps||[]).map(Number),marker:Number(rec.marker)||0}}const newEnds={};for(const [oldKey,t] of Object.entries(data.raceEnds||{})){const oldRace=oldKey.split(':')[1];if(raceMapping[oldRace])newEnds[`${sid}:${raceMapping[oldRace]}`]=Number(t)}setClasses(old=>[...old,{...data.class,id:cid,students:importedStudents}]);setSessions(old=>[{...data.session,id:sid,classId:cid,name:data.session.name+' (test)',races:importedRaces},...old]);setRecords(old=>({...old,...newRecords}));setRaceEnds(old=>({...old,...newEnds}));setClassId(cid);setSessionId(sid);setRaceId(importedRaces[0].id);setStatus('idle');setTab('bilans');alert('Simulation chargée : les quatre courses et les résultats sont visibles dans Bilans. Les données existantes sont conservées.')}catch(err){alert('Import impossible : '+err.message)}e.target.value=''}
function exportResults(){const rows=[];for(const ses of sessions.filter(s=>s.classId===classId))for(const r of ses.races)for(const s of cls.students.filter(s=>s.group===r.group)){const rec=records[`${ses.id}:${r.id}:${s.id}`]||{laps:[],marker:0};const dist=rec.laps.length*200+(rec.marker||0);const target=targetFor(s,r.duration);const durations=rec.laps.map((t,i)=>t-(rec.laps[i-1]||0));const velocities=durations.map(t=>speed(200,t));const mean=velocities.reduce((a,b)=>a+b,0)/(velocities.length||1);const cv=velocities.length>1&&mean?Math.sqrt(velocities.reduce((a,v)=>a+(v-mean)**2,0)/velocities.length)/mean*100:0;rows.push({Seance:ses.name,Date:ses.date,Course:r.duration+' min',Groupe:r.group,Nom:s.last,Prenom:s.first,Tours:rec.laps.length,'Dernier repere':rec.marker||0,'Distance (m)':dist,'Durée réelle (s)':(raceEnds[`${ses.id}:${r.id}`]??r.duration*60000)/1000,'Vitesse moyenne (km/h)':rnd(speed(dist,raceEnds[`${ses.id}:${r.id}`]??r.duration*60000)),'Cible (km/h)':target,'Ecart projet (%)':target?rnd((speed(dist,raceEnds[`${ses.id}:${r.id}`]??r.duration*60000)/target-1)*100):'','CV tours (%)':velocities.length>1?rnd(cv):'', 'Temps passages (s)':rec.laps.map(t=>(t/1000).toFixed(1)).join(' ; ')})}const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Résultats');XLSX.writeFile(wb,'EPS-regularite-resultats.xlsx')}

function exportEvaluationExcel(){if(!session)return;const rows=cls.students.map(st=>{const auto=evaluateStudent(st,session,records,raceEnds,coachEntries,cls.students),entry=evaluations[`${session.id}:${st.id}`]||{},override=entry.overrides||{};const row={Nom:st.last,Prénom:st.first,Groupe:st.group};let total=0,complete=true;CRITERIA.forEach(([key,label])=>{const v=Object.prototype.hasOwnProperty.call(override,key)?override[key]:auto[key];row[label]=v??'';if(v===null||v===undefined)complete=false;else total+=Number(v)});row['Note finale /20']=complete?total:'';row.Statut=entry.validated?'Validée':complete?'À valider':'À compléter';row.Commentaire=entry.comment||'';return row});const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Évaluation classe');XLSX.writeFile(wb,'EPS-Regularite-Evaluation-'+(cls.name||'classe').replace(/[^a-zA-Z0-9_-]/g,'_')+'.xlsx')}
function exportBackupExcel(){const wb=XLSX.utils.book_new();const add=(name,rows)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows.length?rows:[{Vide:''}]),name);
 add('Classes',classes.flatMap(c=>c.students.map(s=>({ClassID:c.id,Classe:c.name,EleveID:s.id,Nom:s.last,Prenom:s.first,Groupe:s.group,Sexe:s.sex||'',VMA:s.vma||'',Cible12:targetFor(s,12),Cible6:targetFor(s,6),Allure12:s.pace12||'',Allure6:s.pace6||''}))));
 add('Seances',sessions.flatMap(s=>s.races.map(r=>({SeanceID:s.id,ClassID:s.classId,Seance:s.name,Date:s.date,CourseID:r.id,Groupe:r.group,Duree:r.duration,FinMS:raceEnds[`${s.id}:${r.id}`]??''}))));
 add('Passages',Object.entries(records).map(([k,rec])=>({Cle:k,PassagesMS:(rec.laps||[]).join(';'),Repere:rec.marker||0})));
 add('Coach',Object.entries(coachEntries).map(([k,e])=>({Cle:k,CoureurID:e.runnerId||'',DistanceComptee:e.counted??'',FicheIncomplete:e.incomplete?'oui':'non',Proprete:e.messy?'oui':'non',FCIncoherente:e.heartRate?'oui':'non'})));
 add('Evaluations',Object.entries(evaluations).map(([k,e])=>({Cle:k,Corrections:JSON.stringify(e.overrides||{}),Commentaire:e.comment||'',Validee:e.validated?'oui':'non',DateValidation:e.validatedAt||''})));
 add('Notes',sessions.flatMap(s=>classes.find(c=>c.id===s.classId)?.students.map(st=>{const auto=evaluateStudent(st,s,records,raceEnds,coachEntries,classes.find(c=>c.id===s.classId)?.students||[]),e=evaluations[`${s.id}:${st.id}`]||{},row={Seance:s.name,Eleve:st.first+' '+st.last,Validee:e.validated?'oui':'non'};let sum=0,complete=true;CRITERIA.forEach(([k,label])=>{const v=Object.prototype.hasOwnProperty.call(e.overrides||{},k)?e.overrides[k]:auto[k];row[label]=v??'';if(v===null)complete=false;else sum+=v});row.Total=complete?sum:'';return row})||[]));
 XLSX.writeFile(wb,'EPS-Regularite-Sauvegarde-V9.xlsx')}
async function importBackupExcel(event){const file=event.target.files?.[0];if(!file)return;try{if(status==='running')throw Error('Termine la course avant un import');const wb=XLSX.read(await file.arrayBuffer());const read=n=>wb.Sheets[n]?XLSX.utils.sheet_to_json(wb.Sheets[n],{defval:''}):null;const cr=read('Classes'),sr=read('Seances'),pr=read('Passages'),er=read('Evaluations'),coachRows=read('Coach');if(!cr||!sr||!pr||!er)throw Error('Fichier de sauvegarde V8 attendu (4 onglets techniques)');if(!confirm('Importer cette sauvegarde complète ? Les données locales actuelles seront remplacées. Exporte-les auparavant si nécessaire.'))return;
 const cs=[];for(const r of cr){let c=cs.find(x=>x.id===String(r.ClassID));if(!c){c={id:String(r.ClassID),name:String(r.Classe),students:[]};cs.push(c)}c.students.push({id:String(r.EleveID),last:String(r.Nom),first:String(r.Prenom),group:String(r.Groupe),sex:String(r.Sexe||''),vma:Number(r.VMA)||0,target12:Number(r.Cible12)||10,target6:Number(r.Cible6)||11,pace12:parsePace(r.Allure12),pace6:parsePace(r.Allure6)})}
 const ss=[],ends={};for(const r of sr){let x=ss.find(z=>z.id===String(r.SeanceID));if(!x){x={id:String(r.SeanceID),classId:String(r.ClassID),name:String(r.Seance),date:String(r.Date),races:[]};ss.push(x)}x.races.push({id:String(r.CourseID),group:String(r.Groupe),duration:Number(r.Duree)});if(r.FinMS!=='')ends[`${r.SeanceID}:${r.CourseID}`]=Number(r.FinMS)}
 const recs={};for(const r of pr){recs[String(r.Cle)]={laps:String(r.PassagesMS||'').split(';').filter(Boolean).map(Number),marker:Number(r.Repere)||0}}
 const evs={};for(const r of er){evs[String(r.Cle)]={overrides:JSON.parse(String(r.Corrections||'{}')),comment:String(r.Commentaire||''),validated:String(r.Validee)==='oui',validatedAt:String(r.DateValidation||'')}}
 const coaches={};for(const r of coachRows||[]){coaches[String(r.Cle)]={runnerId:String(r.CoureurID||''),counted:r.DistanceComptee===''?'':String(r.DistanceComptee),incomplete:String(r.FicheIncomplete)==='oui',messy:String(r.Proprete)==='oui',heartRate:String(r.FCIncoherente)==='oui'}}
 setCoachEntries(coaches);setClasses(cs);setSessions(ss);setRecords(recs);setRaceEnds(ends);setEvaluations(evs);setClassId(cs[0]?.id||'');setSessionId(ss[0]?.id||null);setStatus('idle');alert('Sauvegarde Excel V8 importée.')}catch(err){alert('Import impossible : '+err.message)}event.target.value=''}
return <div className={"app print-"+printMode}><header><div className="brand"><div className="logo"><img src={`${import.meta.env.BASE_URL}icon-192.png`} alt="Logo Demi-fond Troisième" /></div><div><strong>Demi-fond Troisième</strong><small>Courses · Vitesse · Projet</small></div></div><span className="headerpill">200 m / tour</span></header><nav>{[['classes',Users,'Classes'],['seances',Settings,'Séances'],['course',Timer,'Course'],['coach',Users,'Coach-observateur'],['bilans',BarChart3,'Bilans'],['evaluation',Settings,'Évaluation'],['bareme',BarChart3,'Barème']].map(([id,Icon,label])=><button key={id} className={tab===id?'active':''} onClick={()=>{if(statusRef.current==='running'&&id!=='course'){alert('Termine la course en cours avant de changer d’onglet.');return}setTab(id)}}><Icon size={19}/><span>{label}</span></button>)}</nav><main>{tab==='coach'&&(session?<CoachObserver students={cls.students} session={session} records={records} coachEntries={coachEntries} onChange={setCoachEntries}/>:<div className="notice">Sélectionne une séance dans l'onglet Séances pour évaluer les coachs.</div>)}{tab==='bareme'&&<BaremeEleves/>}{tab==='classes'&&<><div className="heading"><h1>Classes et projets</h1><label className="upload"><Upload size={17}/> Importer Excel<input type="file" accept=".xlsx,.xls" hidden onChange={importExcel}/></label></div><div className="panel"><div className="heading"><h2>Gestion des classes</h2><button onClick={()=>{const name=prompt('Nom de la nouvelle classe :');if(!name?.trim())return;const id=crypto.randomUUID();setClasses(old=>[...old,{id,name:name.trim(),students:[]}]);setClassId(id);setSessionId(null);setStatus('idle')}}><Plus size={16}/> Créer une classe</button></div><label>Classe active</label><select value={classId} onChange={e=>{setClassId(e.target.value);setSessionId(null);setStatus('idle')}}>{classes.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select><label>Renommer la classe</label><input value={cls?.name||""} onChange={e=>setClasses(old=>old.map(c=>c.id===classId?{...c,name:e.target.value}:c))}/><p className="muted">Import attendu : Nom, Prénom et, si disponibles, Groupe, Sexe, VMA, Allure12, Allure6 (Verte, Orange, Rouge, Noire).</p></div><div className="panel"><div className="heading"><h2>Élèves ({cls.students.length})</h2><Button secondary onClick={()=>setClasses(old=>old.map(c=>c.id===classId?{...c,students:[...c.students,{id:crypto.randomUUID(),first:'',last:'',group:'A',target12:10,target6:11,sex:'',vma:0}]}:c))}><Plus size={16}/> Élève</Button></div><div className="tablewrap"><table><thead><tr><th>Nom</th><th>Prénom</th><th>Groupe</th><th>Projet 12 min</th><th>Projet 6 min</th><th>Sexe</th><th>VMA</th><th></th></tr></thead><tbody>{cls.students.map(s=><tr key={s.id}><td><input value={s.last} onChange={e=>updateStudent(s.id,'last',e.target.value)}/></td><td><input value={s.first} onChange={e=>updateStudent(s.id,'first',e.target.value)}/></td><td><select value={s.group} onChange={e=>updateStudent(s.id,'group',e.target.value)}><option>A</option><option>B</option></select></td>{[12,6].map(d=><td key={d}><div className="pace-cell"><select className={'pace-select pace-'+((d===12?s.pace12:s.pace6)||'none')} value={(d===12?s.pace12:s.pace6)||''} onChange={e=>updateStudent(s.id,d===12?'pace12':'pace6',e.target.value)}><option value="">Choisir l’allure</option>{PACES.map(p=><option key={p.id} value={p.id}>{p.label}</option>)}</select><small className="pace-target">{paceById(d===12?s.pace12:s.pace6)&&Number(s.vma)>0?`${rnd(targetFor(s,d))} km/h`:'VMA à renseigner / allure à choisir'}</small></div></td>)}<td><select value={s.sex||''} onChange={e=>updateStudent(s.id,'sex',e.target.value)}><option value="">—</option><option value="F">Fille</option><option value="G">Garçon</option></select></td><td><input type="number" min="0" max="30" step="0.1" value={s.vma||''} onChange={e=>updateStudent(s.id,'vma',Number(e.target.value))}/></td><td><button className="iconbtn danger" onClick={()=>{if(confirm('Supprimer cet élève ?'))setClasses(old=>old.map(c=>c.id===classId?{...c,students:c.students.filter(x=>x.id!==s.id)}:c))}}>×</button></td></tr>)}</tbody></table></div></div></>}
{tab==='seances'&&<><div className="heading"><h1>Séances</h1><Button onClick={addSession}><Plus size={17}/> Nouvelle séance</Button></div><div className="panel"><label>Séance active</label><select value={sessionId||''} onChange={e=>{setSessionId(e.target.value);setStatus('idle')}}><option value="">Sélectionner</option>{sessions.filter(s=>s.classId===classId).map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select>{session&&<><label>Nom de la séance</label><input value={session.name} onChange={e=>setSessions(old=>old.map(s=>s.id===session.id?{...s,name:e.target.value}:s))}/><h2>Programme des courses</h2><div className="racegrid">{session.races.map((r,i)=><div className="racebox" key={r.id}><div style={{display:'flex',alignItems:'center',justifyContent:'space-between',gap:8}}><b>Course {i+1}</b><button type="button" aria-label={'Supprimer la course '+(i+1)} title="Supprimer la course" disabled={status==='running'||session.races.length<=1} onClick={()=>removeRace(r.id)} style={{background:'#fee2e2',color:'#b91c1c',border:'1px solid #fecaca',borderRadius:8,width:34,height:34,fontSize:23,lineHeight:1,cursor:'pointer',opacity:status==='running'||session.races.length<=1?0.4:1}}>×</button></div><label>Groupe</label><select value={r.group} onChange={e=>setSessions(old=>old.map(s=>s.id===session.id?{...s,races:s.races.map(x=>x.id===r.id?{...x,group:e.target.value}:x)}:s))}><option>A</option><option>B</option></select><label>Durée (minutes)</label><input type="number" min="3" max="40" value={r.duration} onChange={e=>setSessions(old=>old.map(s=>s.id===session.id?{...s,races:s.races.map(x=>x.id===r.id?{...x,duration:Math.max(3,Math.min(40,Number(e.target.value)||3))}:x)}:s))}/><Button secondary onClick={()=>{selectRace(r.id);setTab('course')}}>Ouvrir la course</Button></div>)}</div><Button secondary onClick={()=>setSessions(old=>old.map(s=>s.id===session.id?{...s,races:[...s.races,{id:crypto.randomUUID(),group:'A',duration:8}]}:s))}><Plus size={16}/> Ajouter une course</Button></>}</div></>}
{tab==='course'&&<><div className="heading"><h1>Chronométrage</h1><span className={'state '+status}>{status==='running'?'● En cours':status==='finished'?'✓ Terminée':'Prêt au départ'}</span></div>{!session&&<div className="notice">Crée une séance dans l’onglet Séances pour démarrer le chronométrage.</div>}<div className="panel"><div className="race-tabs">{races.map((r,i)=><button key={r.id} className={race.id===r.id?'selected':''} onClick={()=>selectRace(r.id)}>Course {i+1}<small>{r.group} · {r.duration} min</small></button>)}</div><div className="clock"><small>TEMPS ÉCOULÉ</small><strong>{fmt(elapsed)}</strong><span>Restant : {fmt(maxMs-elapsed)} / {race.duration} min</span><div className="progress"><div style={{width:`${Math.min(100,elapsed/maxMs*100)}%`}}/></div><div className="actions">{status!=='running'?<Button onClick={start}><Play size={18}/> {status==='finished'?'Recommencer':'Démarrer'}</Button>:<Button secondary onClick={()=>stop(startRef.current===null?elapsedRef.current:performance.now()-startRef.current,true)}><Square size={18}/> Arrêt anticipé</Button>}</div></div></div><div className="heading"><h2>Pointage · Groupe {race.group} ({students.length})</h2><div className="toggle"><label className="sort-label">Ordre <select value={courseSort} onChange={e=>setCourseSort(e.target.value)}><option value="speed">Plus rapide → plus lent</option><option value="name">Alphabétique</option></select></label><button className={view==='cards'?'on':''} onClick={()=>setView('cards')}>Cartes</button><button className={view==='list'?'on':''} onClick={()=>setView('list')}>Liste</button></div></div><div className={view==='cards'?'students cards':'students list'}>{sortedStudents.map(s=>{const rec=getRec(s.id),last=rec.laps.at(-1)||0,prev=rec.laps.at(-2)||0,velocity=last?speed(200,last-prev):0,target=targetFor(s,race.duration),delta=target&&velocity?(velocity/target-1)*100:null;return <div key={s.id} className="student"><button type="button" style={{touchAction:"manipulation"}} className="point" disabled={!canPoint} onClick={()=>point(s)}><span className="studentname">{s.first} <b>{s.last}</b></span><span className="studentstats"><b>{rec.laps.length} tours</b><small>{rec.laps.length*200} m</small></span><span className="velocity">{last?rnd(velocity)+' km/h':'—'}<small>Cible {target} km/h</small></span>{delta!==null&&<span className={'delta '+(Math.abs(delta)<5?'good':Math.abs(delta)<10?'warn':'bad')}>{delta>0?'+':''}{rnd(delta)} %</span>}<Plus className="plus" size={21}/></button><button type="button" style={{touchAction:"manipulation"}} className="undo" title="Annuler dernier passage" disabled={!rec.laps.length||status==='idle'} onClick={()=>undo(s)}><Undo2 size={16}/></button></div>})}</div>{status==='finished'&&<div className="panel"><h2>Arrivée · Derniers repères</h2><p className="muted">Durée réelle : {fmt(raceEnds[`${sessionId}:${race.id}`]??maxMs)}. Tu peux corriger les passages après l'arrêt.</p><p className="muted">Saisis la distance parcourue après le dernier passage complet. Un élève qui termine exactement sur la ligne reçoit 0 m supplémentaire.</p><div className="markers">{students.map(s=>{const rec=getRec(s.id);return <div className="marker" key={s.id}><strong>{s.first} {s.last}</strong><span>{rec.laps.length} tours</span><button className="secondary" onClick={()=>{setEditStudent(editStudent===s.id?null:s.id);setEditIndex(-1);setManualTime('')}}>Corriger les passages</button><select value={rec.marker||0} onChange={e=>setFinalMarker(s,e.target.value)}>{[0,25,50,75,100,125,150,175].map(v=><option key={v} value={v}>{v} m</option>)}</select><b>{rec.laps.length*200+(rec.marker||0)} m</b></div>})}</div>{students.filter(s=>s.id===editStudent).map(s=>{const rec=getRec(s.id);return <div className="correction" key={s.id}><h3>Passages de {s.first} {s.last}</h3><p className="muted">Temps cumulés depuis le départ. Ajoute, modifie ou supprime un passage de 200 m.</p>{rec.laps.map((t,i)=><div className="correction-row" key={i}><strong>Tour {i+1}</strong><span>{fmt(t)}</span><span>{fmt(t-(rec.laps[i-1]||0))} / tour</span><button className="secondary" onClick={()=>{setEditIndex(i);setManualTime(formatPassage(t))}}>Modifier</button><button className="secondary" onClick={()=>deletePassage(s,i)}>Supprimer</button></div>)}<div className="correction-form"><label>{editIndex>=0?`Modifier le tour ${editIndex+1}`:'Ajouter un passage oublié'}<input placeholder="1.10" value={manualTime} onChange={e=>setManualTime(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){e.preventDefault();savePassage(s,editIndex)}}}/></label><Button onClick={()=>savePassage(s,editIndex)}>{editIndex>=0?'Enregistrer la modification':'Ajouter le passage'}</Button>{editIndex>=0&&<Button secondary onClick={()=>{setEditIndex(-1);setManualTime('')}}>Annuler</Button>}</div></div>})}<Button onClick={()=>setTab('bilans')}><BarChart3 size={18}/> Voir les bilans</Button></div>}</>}
{tab==='bilans'&&<><div className="heading"><h1>Bilans et résultats</h1><div style={{display:"flex",gap:8,flexWrap:"wrap"}}><label className="upload"><Upload size={17}/> Charger simulation JSON<input type="file" accept=".json,application/json" hidden onChange={importSimulation}/></label><Button onClick={exportResults}><Download size={17}/> Export Excel</Button></div></div><div className="panel"><p className="muted">Résultats calculés pour chaque course. Les vitesses par tour utilisent uniquement les passages complets. La vitesse moyenne finale utilise le dernier repère saisi.</p><div className="tablewrap"><table><thead><tr><th>Élève</th><th>Course</th><th>Tours</th><th>Distance</th><th>Vitesse moyenne</th><th>Projet</th><th>Écart à la vitesse cible</th><th>Vitesses des tours (km/h)</th><th>Correction</th></tr></thead><tbody>{(cls?.students||[]).slice().sort((a,b)=>(a.last||'').localeCompare(b.last||'','fr')).flatMap(st=>{const matching=session?.races.filter(r=>r.group===st.group)||[];return matching.map((r,i)=>{const rec=getRec(st.id,r.id),distance=rec.laps.length*200+(rec.marker||0),v=speed(distance,raceEnds[`${sessionId}:${r.id}`]??r.duration*60000),target=targetFor(st,r.duration);return <tr key={r.id+st.id} className={i===0?'student-group-first':''}><td>{i===0?<strong>{st.first} {st.last}</strong>:<span className="muted">↳ même élève</span>}</td><td>{r.duration} min ({r.group})</td><td>{rec.laps.length}</td><td>{distance} m</td><td>{rec.laps.length||rec.marker?rnd(v):'—'}</td><td>{target} km/h</td><td>{target&&(rec.laps.length||rec.marker)?rnd((v/target-1)*100)+' %':'—'}</td><td>{rec.laps.map((t,j)=>rnd(speed(200,t-(rec.laps[j-1]||0)))).join(' · ')||'—'}</td><td><button className="secondary" onClick={()=>editFromBilans(r,st)}>Modifier</button></td></tr>})})}</tbody></table></div></div>{session&&<><div className="panel"><div className="heading"><h2>Bilans individuels et graphiques</h2></div><div className="student-navigation"><button className="secondary" disabled={!cls.students.length} onClick={()=>{const idx=cls.students.findIndex(s=>s.id===reportStudentId);setReportStudentId(cls.students[(idx<=0?cls.students.length:idx)-1]?.id||'')}}>← Élève précédent</button><button className="secondary" disabled={!cls.students.length} onClick={()=>{const idx=cls.students.findIndex(s=>s.id===reportStudentId);setReportStudentId(cls.students[(idx+1)%cls.students.length]?.id||'')}}>Élève suivant →</button></div><label htmlFor="report-student">Choisir un élève</label><select id="report-student" value={cls.students.some(s=>s.id===reportStudentId)?reportStudentId:''} onChange={e=>setReportStudentId(e.target.value)}><option value="">Sélectionner un élève</option>{cls.students.map(s=><option key={s.id} value={s.id}>{s.first} {s.last} · Groupe {s.group}</option>)}</select><p className="muted">Choisis un élève pour voir ses deux courbes et leur comparaison.</p></div>{cls.students.filter(s=>s.id===reportStudentId).map(s=><StudentReport key={s.id} student={s} races={session.races} records={records} sessionId={sessionId} raceEnds={raceEnds} onEdit={editFromBilans}/>)}</>}</>}
{tab==='evaluation'&&<><div className="heading"><h1>Évaluation sur 20</h1><div className="eval-actions"><label className="upload"><Upload size={16}/> Importer sauvegarde Excel<input type="file" accept=".xlsx" hidden onChange={importBackupExcel}/></label><button onClick={exportBackupExcel}><Download size={16}/> Sauvegarde complète</button><button onClick={exportEvaluationExcel}><Download size={16}/> Tableau notes Excel / WPS</button><button className="secondary" onClick={()=>{setPrintMode('class');setTimeout(()=>window.print(),100)}}>PDF classe A4</button><button className="secondary" onClick={()=>{setPrintMode('student');setTimeout(()=>window.print(),200)}}>PDF élève A4</button></div></div>{!session?<div className="notice">Sélectionne une séance dans l'onglet Séances.</div>:<><CollectiveAssessment students={cls.students} session={session} records={records} raceEnds={raceEnds} coachEntries={coachEntries} evaluations={evaluations} onSelect={id=>{setEvalStudentId(id);setEvalReportOpen(false)}}/><div className="panel"><div className="student-navigation"><button className="secondary" onClick={()=>{const idx=cls.students.findIndex(s=>s.id===evalStudentId);const next=(idx<=0?cls.students.length:idx)-1;setEvalStudentId(cls.students[next]?.id||'');setEvalReportOpen(false)}} disabled={!cls.students.length}>← Élève précédent</button><button className="secondary" onClick={()=>{const idx=cls.students.findIndex(s=>s.id===evalStudentId);setEvalStudentId(cls.students[(idx+1)%cls.students.length]?.id||'');setEvalReportOpen(false)}} disabled={!cls.students.length}>Élève suivant →</button></div><label>Élève</label><select value={evalStudentId} onChange={e=>{setEvalStudentId(e.target.value);setEvalReportOpen(false)}}><option value="">Sélectionner un élève</option>{cls.students.map(s=><option key={s.id} value={s.id}>{s.first} {s.last}</option>)}</select><p className="muted">Performance 6 pts · Respect du projet 4 · Régularité 3 · Choix des allures 4 · Coach 3. Deux allures identiques = 0/4 pour le choix. Dépassement de la cible jusqu’à +10 % non pénalisé ; au-delà, malus de 1 point par course. Les critères non calculables restent non notés.</p></div>{cls.students.filter(s=>s.id===evalStudentId).map(s=><React.Fragment key={s.id}><GradeEditor student={s} session={session} records={records} raceEnds={raceEnds} coachEntries={coachEntries} classStudents={cls.students} entry={evaluations[`${sessionId}:${s.id}`]} onChange={v=>setEvaluations(old=>({...old,[`${sessionId}:${s.id}`]:v}))} onOpenReport={()=>setEvalReportOpen(x=>!x)}/>{evalReportOpen&&<div className="eval-embedded-report"><StudentReport student={s} races={session.races} records={records} sessionId={sessionId} raceEnds={raceEnds} onEdit={editFromBilans}/></div>}</React.Fragment>)}</>}</>}
</main>{printMode==='student'&&<PrintableStudentSheets students={cls?.students||[]} session={session} records={records} raceEnds={raceEnds} coachEntries={coachEntries} evaluations={evaluations}/>}<footer>Demi-fond Troisième · Version 15 · Données conservées dans ce navigateur · Fonctionne sans compte</footer></div>}
createRoot(document.getElementById('root')).render(<App/>);
if(import.meta.env.PROD&&'serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`,{scope:import.meta.env.BASE_URL}).catch(err=>console.warn('Mode hors ligne indisponible',err)));}

